      read: 'あなたの持っているスマートフォンや服の多くは、外国で部品がつくられ、別の国で組み立てられて日本に届いています。このような国境をこえた分業を支えているのが、【コンテナ】とよばれる大きさのそろった鉄の箱です。\nコンテナが広まる前、船の荷物は袋や木箱、たるなど形も大きさもばらばらでした。港では大勢の港湾労働者が一つ一つ手で積み下ろしをしたので、船は港に何日もとまり、荷物の盗難や破損も多く、費用もかかりました。\n1950年代、アメリカの運送業者マルコム・マクリーンは、トラックの荷台ごと船に積めばよいと考えました。1956年、改造したタンカーに荷物を詰めた箱を積んで運んだのが、コンテナ輸送の始まりとされます。やがてコンテナの大きさが国際的にそろえられると、同じ箱を船・鉄道・トラックでそのまま乗りかえられるようになりました。\n積み下ろしの時間と費用は大きく減り、遠い国でつくった製品を安く運べるようになりました。工場が人件費の安いアジアの国々へ移り、世界中の部品が組み合わさる時代は、この「ただの箱」なしには考えられません。グローバル化は、地味な技術の工夫にも支えられているのです。'
