      univ: '大学の考古学では、発掘調査で出土した遺物を測量・分析し、年代や当時の暮らしを復元します。DNA分析によって、縄文人と弥生時代の渡来系の人々の関係を調べる研究も進んでいます。',
      readT: '錆の下から現れた115文字──稲荷山古墳の鉄剣',
      read: '埼玉県行田市の稲荷山古墳から鉄剣が出土したのは、1968年のことでした。鉄剣は赤く錆びていて、見た目には何の変哲もない古い剣にすぎませんでした。\n10年後の1978年、保存処理のためにこの剣をX線で撮影したところ、研究者たちは息をのみました。錆の下に、金で文字を象嵌(金属に溝を彫って金をはめこむ技法)した銘文が浮かび上がったのです。剣の表と裏には、あわせて115文字が刻まれていました。\n銘文には「辛亥年」という年と、「ヲワケ」という人物が、先祖代々大王に仕えてきたこと、そして自分が「ワカタケル大王」の政治を助けたことが記されていました。辛亥年は471年と考えられています。また、熊本県の江田船山古墳から出土していた大刀の文字も、この発見によって同じ大王の名と読めるようになりました。\nこの発見で、5世紀後半のヤマト政権の支配が関東から九州にまで及んでいたことが、日本列島の中から見つかった文字によって確かめられました。中国の歴史書にたよるしかなかった時代の歴史に、日本列島の人々自身が書いた記録が加わった瞬間でした。錆びた1本の剣が、教科書を書きかえたのです。'
