        fix: '文字の使い分けを【公的な場/私的な場】で整理します。役所の文書や男性貴族の日記は漢文で書かれ、和歌や物語・女性の日記などにかなが使われました。かなは漢字の代わりではなく、漢字と並んで使われる文字だったのです。',
