      next: 'イスラーム世界は、【中世ヨーロッパ】の十字軍や学問(12世紀ルネサンス)と深くかかわります。のちにオスマン帝国・サファヴィー朝・ムガル帝国の時代(アジアの近世の単元)へと続きます。',
