      read: '15世紀のはじめ、明の永楽帝の命を受けた【鄭和】は、大艦隊を率いて南の海へ乗り出しました。航海は1405年から7回にわたり、東南アジア、インド、アラビア半島、そしてアフリカ東岸にまで達しました。艦隊の中心となった大型船は、コロンブスの船よりはるかに大きかったといわれます。\n鄭和はイスラーム教徒の家に生まれた宦官でした。航海の目的は、領土を奪うことではなく、明の皇帝の権威を各地に示し、多くの国々に朝貢をうながすことでした。実際に、この航海をきっかけに数多くの国の使節が明に来るようになりました。\nこの航海で、中国の人々をおどろかせた贈り物がありました。アフリカ東岸の国からもたらされた【キリン】です。首の長いこの動物は、中国の伝説で、すぐれた君主が現れたときに姿を見せるという聖なる動物「麒麟」だとして、宮廷で大切に扱われました。日本語でこの動物を「キリン」とよぶのも、ここに由来するといわれています。\nしかし、永楽帝の死後、大航海は打ち切られました。費用が大きすぎたことや、北方のモンゴルへの備えが優先されたことが理由とされます。その後、インド洋に大艦隊を送ったのは、ヨーロッパの国々でした。'
